export const SceneSpeedActivationMode = {
    SPIN_WINDOW: 'spin-window',
    GAME_WIDE: 'game-wide',
} as const;

export type SceneSpeedActivationMode = typeof SceneSpeedActivationMode[keyof typeof SceneSpeedActivationMode];

export interface SceneSpeedOverride {
    // 整體加速倍數 1 不加速 對應getTurboIndex
    speedFactors: [number, number, number];
    activationMode: SceneSpeedActivationMode;
}

function parseOverride(value: unknown): SceneSpeedOverride | null {
    if (!value || typeof value !== 'object') return null;
    const obj = value as Record<string, unknown>;
    const arr = obj.speedFactors;
    if (!Array.isArray(arr) || arr.length !== 3 || !arr.every((v) => typeof v === 'number')) return null;
    const activationMode = obj.activationMode === SceneSpeedActivationMode.GAME_WIDE
        ? SceneSpeedActivationMode.GAME_WIDE
        : SceneSpeedActivationMode.SPIN_WINDOW;
    return { speedFactors: [arr[0], arr[1], arr[2]], activationMode };
}

/**
 * 整體 scene 加速 純資料儲存
 * DirectorSpeedHook 攔截 director.tick(dt) 套用
 * 存儲 localStorage 覆寫值優先 次為localDefault（sceneSpeed.json 載入）gameId 分開儲存
 */
export default class SceneSpeedStore {
    private static readonly localDefaults = new Map<string, SceneSpeedOverride>();
    private static readonly listeners = new Map<string, Set<(value: SceneSpeedOverride) => void>>();

    private static storageKey(gameId: string): string {
        return `slot_scene_speed_${gameId}`;
    }

    public static setLocalDefault(gameId: string, value: SceneSpeedOverride): void {
        SceneSpeedStore.localDefaults.set(gameId, value);
        SceneSpeedStore.notify(gameId);
    }

    public static getLocalDefault(gameId: string): SceneSpeedOverride | null {
        return SceneSpeedStore.localDefaults.get(gameId) ?? null;
    }

    public static get(gameId: string): SceneSpeedOverride | null {
        const override = SceneSpeedStore.getStoredOverride(gameId);
        if (override) return override;
        return SceneSpeedStore.localDefaults.get(gameId) ?? null;
    }

    private static getStoredOverride(gameId: string): SceneSpeedOverride | null {
        if (typeof localStorage === 'undefined') return null;
        try {
            const raw = localStorage.getItem(SceneSpeedStore.storageKey(gameId));
            if (!raw) return null;
            return parseOverride(JSON.parse(raw));
        } catch (e) {
            console.warn('[SceneSpeedStore] 讀取失敗', e);
        }
        return null;
    }

    public static set(gameId: string, value: SceneSpeedOverride): void {
        if (typeof localStorage !== 'undefined') {
            try {
                localStorage.setItem(SceneSpeedStore.storageKey(gameId), JSON.stringify(value));
            } catch (e) {
                console.warn('[SceneSpeedStore] 寫入失敗', e);
            }
        }
        SceneSpeedStore.notify(gameId, value);
    }

    public static clear(gameId: string): void {
        if (typeof localStorage !== 'undefined') {
            localStorage.removeItem(SceneSpeedStore.storageKey(gameId));
        }
        SceneSpeedStore.notify(gameId);
    }

    public static subscribe(gameId: string, listener: (value: SceneSpeedOverride) => void): () => void {
        const listeners = SceneSpeedStore.listeners.get(gameId) ?? new Set();
        listeners.add(listener);
        SceneSpeedStore.listeners.set(gameId, listeners);
        const current = SceneSpeedStore.get(gameId);
        if (current) listener(current);
        return () => {
            listeners.delete(listener);
            if (listeners.size === 0) SceneSpeedStore.listeners.delete(gameId);
        };
    }

    private static notify(gameId: string, value = SceneSpeedStore.get(gameId)): void {
        if (!value) return;
        for (const listener of Array.from(SceneSpeedStore.listeners.get(gameId) ?? [])) {
            listener(value);
        }
    }
}
