import { _decorator, Component, Node, Sprite, SpriteFrame, tween, Tween, UITransform } from 'cc';
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from '../events/GameRuntimeEventBus';
import { GAMESTOREMAP } from '../store/StoreMap';

const { ccclass, property } = _decorator;

/**
 * 中獎累計條閒置時的圖片跑馬燈
 * 只在 NEW_GAME 閒置狀態跑 轉動與中獎演出一律讓位給金額與倍率
 */
@ccclass('1001/WinBarMarqueeView')
export class WinBarMarqueeView extends Component {
    @property({ type: Node, tooltip: '裁切範圍 掛 cc.Mask 的節點 圖只在這個寬度內看得到' })
    maskNode: Node = null!;

    @property({ type: Sprite, tooltip: '實際捲動的圖 放在 maskNode 底下 錨點維持預設 0.5' })
    marqueeSprite: Sprite = null!;

    @property({ type: [SpriteFrame], tooltip: '輪播的圖 依陣列順序循環' })
    frames: SpriteFrame[] = [];

    @property({ type: [Node], tooltip: '跑馬燈期間要藏起來的節點 拉 num 跟 mul' })
    hideDuringMarquee: Node[] = [];

    @property({ tooltip: '回到閒置後隔幾秒才切成跑馬燈' })
    idleDelay = 3;

    @property({ tooltip: '圖比裁切範圍窄時 置中停留秒數' })
    holdDuration = 4;

    @property({ tooltip: '圖比裁切範圍寬時 從右捲到左的秒數' })
    scrollDuration = 6;

    @property({ tooltip: '捲動前後各自的靜止秒數' })
    gapDuration = 1;

    // 播到第幾張 停掉再開會從下一張接著播
    private index = -1;
    private marqueeTween: Tween<Node> | null = null;
    private running = false;
    // 藏起來之前的顯示狀態 倍率平常就是關著的 不能一律開回來
    private savedActive: boolean[] = [];
    private unsubscribe: (() => void) | null = null;
    private readonly onIdleTimeout = (): void => { this.play(); };

    protected override onLoad(): void {
        // 預設不顯示 開始跑才出現
        if (this.marqueeSprite?.node?.isValid) this.marqueeSprite.node.active = false;
        this.unsubscribe = gameRuntimeEventBus.on(GAME_EVENT_TYPE.SPIN_STATUS_CHANGED, (event) => this.applyStatus(event.status));
    }

    protected override start(): void {
        if (this.validFrames.length === 0) console.warn('[WinBarMarquee] frames 沒有圖 跑馬燈不會啟動');
        // 剛進遊戲就是閒置 而且 setSpinStatus 同值不發事件 這裡不能等事件
        this.scheduleOnce(this.onIdleTimeout, this.idleDelay);
    }

    protected override onDestroy(): void {
        this.unsubscribe?.();
        this.unsubscribe = null;
        this.stop();
    }

    private applyStatus(status: string): void {
        if (status === GAMESTOREMAP.NEW_GAME) {
            if (!this.running) this.scheduleOnce(this.onIdleTimeout, this.idleDelay);
            return;
        }
        this.stop();
    }

    private stop(): void {
        this.unschedule(this.onIdleTimeout);
        this.marqueeTween?.stop();
        this.marqueeTween = null;
        if (this.marqueeSprite?.node?.isValid) this.marqueeSprite.node.active = false;
        if (this.running) {
            this.running = false;
            this.setOthersVisible(true);
        }
    }

    private play(): void {
        if (this.running || !this.isReady()) return;
        this.running = true;
        this.setOthersVisible(false);
        this.marqueeSprite.node.active = true;
        this.playNext();
    }

    private setOthersVisible(visible: boolean): void {
        this.hideDuringMarquee.forEach((node, i) => {
            if (!node?.isValid) return;
            if (visible) {
                node.active = this.savedActive[i] ?? true;
            } else {
                this.savedActive[i] = node.active;
                node.active = false;
            }
        });
    }

    // 陣列開了格子但沒拖圖進來的空位要濾掉 不然會播出一張空的
    private get validFrames(): SpriteFrame[] {
        return this.frames.filter((frame) => !!frame);
    }

    private isReady(): boolean {
        return !!(this.maskNode?.isValid && this.marqueeSprite?.node?.isValid && this.validFrames.length > 0);
    }

    private playNext(): void {
        if (!this.isReady()) {
            this.stop();
            return;
        }

        const frames = this.validFrames;
        this.index = (this.index + 1) % frames.length;
        this.marqueeSprite.spriteFrame = frames[this.index];

        const spriteNode = this.marqueeSprite.node;
        // spriteFrame 換過才量得到這張的實際寬度
        const spriteWidth = spriteNode.getComponent(UITransform)!.width;
        const maskWidth = this.maskNode.getComponent(UITransform)!.width;

        if (spriteWidth <= maskWidth) {
            spriteNode.setPosition(0, spriteNode.position.y);
            this.marqueeTween = tween(spriteNode)
                .delay(this.holdDuration)
                .call(() => this.playNext())
                .start();
            return;
        }

        // 進出場都要完全離開裁切範圍
        const edge = (maskWidth + spriteWidth) * 0.5;
        spriteNode.setPosition(edge, spriteNode.position.y);
        this.marqueeTween = tween(spriteNode)
            .delay(this.gapDuration)
            .to(this.scrollDuration, { x: -edge })
            .delay(this.gapDuration)
            .call(() => this.playNext())
            .start();
    }
}
