import SlotWebSocketClient, { SlotWebSocketClientOptions } from './SlotWebSocketClient';
import type {
    SlotApiBetDetailResponse,
    SlotApiBetRequest,
    SlotApiBetHistoryResponse,
    SlotApiEntryResponse,
    SlotApiEnvelope,
    SlotApiFrame,
    SlotApiGameInfoResponse,
    SlotApiGameStateResponse,
    SlotApiHistoryListResponse,
    SlotApiHistoryRoundResponse,
    SlotApiJackpotsResponse,
    SlotApiGetGameResponse,
    SlotApiJackpotPoolSnapshot,
    SlotApiJackpotUnsubscribeResponse,
    SlotApiRequestType,
    SlotApiSpinResponse,
    SlotApiStepObject
} from './SlotApiTypes';
import { SLOT_API_CODE, SlotApiHttpError } from './SlotApiTypes';
import { GameNet } from './GameNetHandler';
import { RestClient, RestClientError } from './RestClient';

export interface SlotApiClientOptions {
    httpBaseUrl: string;
    wsUrl?: string;
}
/**
 * SlotApiClient
 *
 * 玩家端 API v5.1 走 HTTP（entry、bet、jackpots、history，見上方各方法），回應不經過 GameNet，
 * 由呼叫端轉成舊格式後用 dispatch() 交給 Handler。
 * 舊協定（mock 還在用）走 WebSocket：委派給 SlotWebSocketClient（request/response + correlation_id），
 * 收到回應時**額外**透過 GameNet 依 `frame.type` 分派給對應的 GameNetHandler，
 * 讓「這筆回應要更新哪個 Store／emit 哪個事件」的邏輯集中在各自的 Handler class 裡
 * （比照 SGEngine 的封包處理器模式）。
 */

/** bet 每秒最多 10 次（附錄 B），兩次請求至少間隔這麼久 */
const BET_MIN_INTERVAL_MS = 100;

export class SlotApiClient {
    private readonly restClient: RestClient;
    private readonly gameNet = new GameNet();
    private wsClient: SlotWebSocketClient | null = null;
    private frameUnsubscribe: (() => void) | null = null;

    private token: string | null = null; // 保存給 getAuthHeaders ws 使用
    constructor(
        private readonly options: SlotApiClientOptions,
        private readonly wsClientOptions: Omit<SlotWebSocketClientOptions, 'url' | 'token'> = {}
    ) {
        this.restClient = new RestClient({
            baseUrl: options.httpBaseUrl,
            // HTTP 請求 5xx／逾時重試 2 次、4xx 不重試；bet 依文件自己重送，不走這個（見 bet）
            timeoutMs: 15000,
            retries: 2,
            retryDelayMs: 300,
            getAuthHeaders: () => ({
                ...(this.token && {
                    Authorization: `Bearer ${this.token}`
                })
            })
        });
    }

    /** 設定玩家端 token（大廳 launch 的 `t`），之後的 HTTP 請求都帶 `Authorization: Bearer` */
    public setToken(token: string): void {
        this.token = token;
    }

    /** 註冊一個 GameNetHandler；同一個 key 只能有一個 Handler */
    public registerHandler(handler: Parameters<GameNet['register']>[0]): void {
        this.gameNet.register(handler);
    }

    // ===== REST：玩家端 API v5.1（slot-integration.md §5） =====

    /** 進場：每次載入遊戲都打，回傳限紅、檔位、`next_step`、`last_step`（§5.1） */
    public async entry(gameId: string): Promise<SlotApiEntryResponse> {
        return this.postPlayer<SlotApiEntryResponse>('/player/entry', { game_id: gameId });
    }

    /** 獎池水位；不依幣別過濾，呼叫端要自己比對 currency（§5.7，30 次／分） */
    public async jackpots(gameId: string): Promise<SlotApiJackpotsResponse> {
        return this.getPlayer<SlotApiJackpotsResponse>('/player/jackpots', { game_id: gameId });
    }

    /** 注單列表（頁碼），只列已結算的局（§5.4） */
    public async historyList(gameId: string, page: number, pageSize: number): Promise<SlotApiHistoryListResponse> {
        return this.getPlayer<SlotApiHistoryListResponse>('/player/history', { game_id: gameId, page, page_size: pageSize });
    }

    /** 單局重播：回母單與全部細單（§5.4） */
    public async historyRound(roundId: string): Promise<SlotApiHistoryRoundResponse> {
        return this.getPlayer<SlotApiHistoryRoundResponse>('/player/history', { round_id: roundId });
    }

    /**
     * 下注；開新局與續打（連消、免費遊戲）同一支，由 prev_step_id 決定（§5.2）。
     * 暫時性失敗依附錄 B 用**同一個** prev_step_id 重送，其他錯誤直接丟出。
     * @throws SlotApiHttpError
     */
    public async bet(request: SlotApiBetRequest): Promise<SlotApiStepObject> {
        for (let attempt = 0; ; attempt++) {
            await this.waitBetInterval();
            try {
                return await this.postPlayer<SlotApiStepObject>('/player/bet', request, 0);
            } catch (error) {
                const delayMs = error instanceof SlotApiHttpError ? this.betRetryDelayMs(error, attempt) : null;
                if (delayMs === null) throw error;
                await new Promise<void>((resolve) => setTimeout(resolve, delayMs));
            }
        }
    }

    /**
     * bet 失敗後要等多久再重送（毫秒）；null＝不重送。
     * 文件有寫的照文件：4017／4022 間隔 1、2、4 秒（三次）、4029／4030 等 Retry-After、4015 立刻重送。
     * 文件沒寫次數與間隔的（網路逾時、4500），沿用既有的 HTTP 重試：2 次、間隔 300ms 線性遞增。
     */
    private betRetryDelayMs(error: SlotApiHttpError, attempt: number): number | null {
        const pending = error.code === SLOT_API_CODE.WRITE_PENDING || error.code === SLOT_API_CODE.ROUND_BUSY;
        if (attempt >= (pending ? 3 : 2)) return null;
        if (pending) return 1000 * 2 ** attempt;
        if (error.code === SLOT_API_CODE.ROUND_VOIDED) return 0;
        if (error.code === SLOT_API_CODE.RATE_LIMITED || error.code === SLOT_API_CODE.SYSTEM_BUSY) return (error.retryAfterSec ?? 1) * 1000;
        if (error.kind === 'network' || error.code === SLOT_API_CODE.INTERNAL) return 300 * (attempt + 1);
        return null;
    }

    private lastBetAt = 0;

    /** 連續打 bet（連消、免費遊戲）時控制在每秒 10 次以內 */
    private async waitBetInterval(): Promise<void> {
        const wait = this.lastBetAt + BET_MIN_INTERVAL_MS - Date.now();
        this.lastBetAt = Date.now() + Math.max(0, wait);
        if (wait > 0) await new Promise<void>((resolve) => setTimeout(resolve, wait));
    }

    /** 把回應交給已註冊的 Handler（HTTP 回應沒有 WS frame，由呼叫端指定類型） */
    public dispatch(type: string, payload: unknown): void {
        this.gameNet.dispatch(type, payload);
    }

    /** 送玩家端 POST；retries 沒給就用 RestClient 預設（5xx／逾時重試 2 次），bet 傳 0 */
    private async postPlayer<T>(path: string, body: unknown, retries?: number): Promise<T> {
        return this.unwrapPlayer(() => this.restClient.post<SlotApiEnvelope<T>>(path, body, { retries }));
    }

    /** 送玩家端 GET，錯誤處理同 postPlayer */
    private async getPlayer<T>(path: string, query: Record<string, string | number>): Promise<T> {
        return this.unwrapPlayer(() => this.restClient.get<SlotApiEnvelope<T>>(path, { query }));
    }

    /**
     * 解開玩家端信封：HTTP 成功但 `code != 0` 的業務錯誤，以及 401／429／5xx，都轉成 SlotApiHttpError。
     * @throws SlotApiHttpError
     */
    private async unwrapPlayer<T>(send: () => Promise<SlotApiEnvelope<T>>): Promise<T> {
        let envelope: SlotApiEnvelope<T>;
        try {
            envelope = await send();
        } catch (error) {
            if (!(error instanceof RestClientError)) throw error;
            const failed = error.body as SlotApiEnvelope | undefined;
            // 401 沒有 code：session 失效，上層要再打一次 entry
            const kind = error.status === 401 ? 'unauthorized' : error.status === undefined ? 'network' : failed?.code ? 'business' : 'http';
            throw new SlotApiHttpError(kind, failed?.code ?? 0, failed?.message ?? error.message, error.status ?? 0, failed?.support_ref, failed?.latest_step_id, error.retryAfterSec);
        }
        if (!envelope || typeof envelope.code !== 'number') {
            throw new Error('玩家端 API 回應格式不符：缺少數字 code');
        }
        if (envelope.code !== 0) {
            throw new SlotApiHttpError('business', envelope?.code ?? 0, envelope?.message ?? 'empty response', 200, envelope?.support_ref, envelope?.latest_step_id);
        }
        return envelope.data as T;
    }

    // ===== WebSocket：連線管理 spin/game-info 等由ws提供=====

    /**
     * 建立並連線 WebSocket；連線後開始把收到的 frame 分派給已註冊的 Handler。
     * 每次呼叫都會關閉舊連線、重新建立（例如 token 過期重新登入後）。
     * token 過期重新登入自動更新保存 可直接呼叫
     */
    public async connect(token: string = this.token ?? ''): Promise<void> {
        this.token = token;
        this.close();
        this.wsClient = new SlotWebSocketClient({ url: this.options.wsUrl, token, ...this.wsClientOptions });
        this.frameUnsubscribe = this.wsClient.onFrame((frame) => this.dispatchFrame(frame));
        await this.wsClient.connect();
    }

    public close(): void {
        this.frameUnsubscribe?.();
        this.frameUnsubscribe = null;
        this.wsClient?.close();
        this.wsClient = null;
    }

    /**
     * 斷線重連成功後觸發 重送 getGameState 更新餘額 下注設定
     * SlotWebSocketClient 處理
     */
    public onReconnect(listener: () => void): () => void {
        return this.getConnectedClient().onReconnect(listener);
    }

    // ===== WebSocket：遊戲流程（spin / history / detail / state） =====

    /** 取得遊戲組態 在 getGameState 之前呼叫 */
    public async slotGetGame(gameCode: string): Promise<SlotApiGetGameResponse> {
        return this.getConnectedClient().getGame(gameCode);
    }

    /** 取得遊戲設定 */
    public async getGameInfo(gameCode: string, currency: string = 'TWD'): Promise<SlotApiGameInfoResponse> {
        return this.getConnectedClient().getGameInfo(gameCode, currency);
    }

    /** 取得目前遊戲狀態 */
    public async getGameState(gameCode: string, tableId?: string): Promise<SlotApiGameStateResponse> {
        return this.getConnectedClient().getGameState(gameCode, tableId);
    }

    /** 送出 Spin 請求 */
    public async spin(gameCode: string, betAmount: string, buyFeature: boolean = false): Promise<SlotApiSpinResponse> {
        return this.getConnectedClient().spin(gameCode, betAmount, buyFeature);
    }

    /** 取得下注歷史 */
    public async getBetHistory(
        gameCode: string,
        limit: number = 20,
        cursor: string = ''
    ): Promise<SlotApiBetHistoryResponse> {
        return this.getConnectedClient().getBetHistory(gameCode, limit, cursor);
    }

    /** 取得單筆下注明細 */
    public async getBetDetail(operationId: string): Promise<SlotApiBetDetailResponse> {
        return this.getConnectedClient().getBetDetail(operationId);
    }

    // ===== WebSocket：Jackpot pool 總獎池

    /** Jackpot pool
     * 無訂閱不會再收到
     * */
    public async getJackpotPool(gameCode: string): Promise<SlotApiJackpotPoolSnapshot> {
        return this.getConnectedClient().getJackpotPool(gameCode);
    }

    /**
     * 訂閱 Jackpot pool 更新
     * 之後的推播無 correlation_id
     */
    public async subscribeJackpotPool(gameCode: string): Promise<SlotApiJackpotPoolSnapshot> {
        return this.getConnectedClient().subscribeJackpotPool(gameCode);
    }

    public async unsubscribeJackpotPool(gameCode: string): Promise<SlotApiJackpotUnsubscribeResponse> {
        return this.getConnectedClient().unsubscribeJackpotPool(gameCode);
    }

    /** 送出請求並等待對應回應（沿用既有的 correlation_id 機制）；回應同時也會經過 Handler 分派 */
    public async request<TPayload = unknown>(
        type: SlotApiRequestType,
        payload?: unknown,
        correlationId?: string
    ): Promise<SlotApiFrame<TPayload>> {
        return this.getConnectedClient().request<TPayload>(type, payload, correlationId);
    }

    private dispatchFrame(frame: SlotApiFrame): void {
        if (!this.gameNet.has(frame.type)) return;
        this.gameNet.dispatch(frame.type, frame.payload);
    }

    /** 取得已連線的 WebSocket client */
    private getConnectedClient(): SlotWebSocketClient {
        if (!this.wsClient) throw new Error('SlotApiClient: connect(token) must complete before sending game requests');
        return this.wsClient;
    }
}
