/** 這支 bundle 對應的玩家端 API `game_id`（slot-integration.md §3.3） */
export const API_GAME_ID = 'eyeofhorus';

// 贏分演出等級門檻
export const WinTier = {
    WIN: 'win',
    BIG: 'big',
    MEGA: 'mega',
    SUPER: 'super',
    EPIC: 'epic',
    TOTAL: 'total',
} as const;
export type WinTier = (typeof WinTier)[keyof typeof WinTier];

// WinTier 由小到大排序 WIN/TOTAL
const WIN_TIER_ORDER: WinTier[] = [WinTier.BIG, WinTier.MEGA, WinTier.SUPER, WinTier.EPIC];

/** 判斷 tier 是否達到 minTier */
export function matchMinWinTier(tier: WinTier | null, minTier: WinTier | null): boolean {
    if (!tier || !minTier) return false;
    const tierIdx = WIN_TIER_ORDER.indexOf(tier);
    const minIdx = WIN_TIER_ORDER.indexOf(minTier);
    if (tierIdx < 0 || minIdx < 0) return false;
    return tierIdx >= minIdx;
}

// 免費遊戲加局時局數數字放大彈回的演出參數 餵給 AppAnimation.playBounce
export const FG_RETRIGGER_BOUNCE = { scaleMultiplier: 1.6, durationUp: 0.18, durationDown: 0.22 } as const;
