/**
 * i18n 初始化輔助工具（狀態邏輯已合併至 base/i18n/LanguageData）
 */
import { JsonAsset } from 'cc';
import { i18nInit, setLanguageMap, currentLanguage, resolveLanguageCode } from './LanguageData';
import AppAssetBundle from '../utils/AppAssetBundle';
import GameConfigManager from '../config/GameConfigManager';

/**
 * 初始化 i18n（手動呼叫）
 * @param defaultLang - 預設語言，如未指定則從 URL ?language= 讀取
 * @param bundleName - 語言 JSON 所在的 bundle，預設目前子遊戲
 */
export async function initI18n(defaultLang?: string, bundleName = GameConfigManager.GAMEID): Promise<void> {
    const urlParams = new URLSearchParams(window.location?.search || '');
    const initLang = defaultLang || urlParams.get('language') || 'zh-HK';

    // 先載入 JSON，再設語言 → 確保 reaction 觸發時語言檔已就緒
    const jsonData = await loadLanguageJson(initLang, bundleName);
    if (jsonData) {
        setLanguageMap(jsonData);
        console.log(`[i18n] 載入成功: ${Object.keys(jsonData).length} 個 key`);
    }

    i18nInit(initLang);
    console.log(`[i18n] 初始化語言: ${currentLanguage.get()}`);
}

/**
 * 切換語言
 * @param lang - 語言碼，如 "zh-CN" 或 "en-US"
 * @param bundleName - 語言 JSON 所在的 bundle，預設目前子遊戲
 */
export async function switchLanguage(lang: string, bundleName = GameConfigManager.GAMEID): Promise<void> {
    // 用 resolveLanguageCode 只做正規化、不觸發 LANGUAGE_CHANGED，
    // 確保新語言的 JSON 先載入、setLanguageMap 完成後，i18nInit 才觸發事件通知 UI 更新，
    // 避免 LocalizedLabel/LocalizedSprite 用舊字典渲染出「切換了但文字沒變」的問題。
    const languageCode = resolveLanguageCode(lang);
    console.log(`[i18n] 切換語言: ${languageCode}`);

    const jsonData = await loadLanguageJson(languageCode, bundleName);
    if (jsonData) {
        setLanguageMap(jsonData);
    }

    i18nInit(lang);
}

/**
 * 載入語言 JSON（從指定 bundle 的 languages 讀取）
 */
async function loadLanguageJson(languageCode: string, bundleName: string): Promise<Record<string, string> | null> {
    const path = `resources/languages/${languageCode}`;

    try {
        await AppAssetBundle.getInstance(bundleName).loadBundle();
        const asset = await AppAssetBundle.getInstance(bundleName).loadAsset(path, JsonAsset);
        return asset.json as Record<string, string>;
    } catch (e) {
        console.warn(`[i18n] 找不到語言檔: ${languageCode}`, e);
        return null;
    }
}
