import { Node, director, sys } from "cc";

/**
 * AppUtility
 * 原生替代 KYCocosSDK/Module/KYUtility.ts，方法簽名 1:1 對應，
 * 供逐步替換 import 路徑使用，KYCocosSDK 內檔案本身不受影響。
 */
export default class AppUtility {

    ///****************** 靜態節點控制 (Persist Root Node) ******************/

    public static setStaticNode(node: Node) {
        director.addPersistRootNode(node);
    }
    public static getStaticNode(name: string): Node | string {
        let node = director.getScene().getChildByName(name);
        return node ? node : `Static node ${name} not found!`;
    }
    public static removeStaticNode(node: Node) {
        director.removePersistRootNode(node);
        node.removeFromParent();
    }
    ///****************** 靜態節點控制 (Persist Root Node) ******************/

    public static setUserDefaultData(key: string, value: any) {
        sys.localStorage.setItem(key, JSON.stringify(value));
    }
    public static getUserDefaultData(key: string): any {
        let value = sys.localStorage.getItem(key);
        return value ? JSON.parse(value) : null;
    }
    public static removeUserDefaultData(key: string) {
        sys.localStorage.removeItem(key);
    }

    // 格式化時間戳為年月日格式
    public static formatDateYMD(timestamp: number): string {
        const date = new Date(timestamp * 1000);
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}/${month}/${day}`;
    }
    public static format(value: number, isKMBT: boolean, decimalPlaces: number = 2): string {
        return isKMBT ? AppUtility.formatCompact(value, decimalPlaces) : AppUtility.formatDecimal(value, decimalPlaces);
    }

    //強制數字兩位數顯示
    public static formatDecimal(value: number, decimalPlaces: number = 2): string {
        const parts = Number(value).toFixed(decimalPlaces).split('.');
        parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
        return parts.join('.');
    }

    /**
     * GC 貨幣模式：超過 5 位數時用 K/M/B/T 單位顯示
     * 規則：整數位 3 位 + 小數位 2 位 = 5 位數以內原樣顯示
     * 超過則除以對應單位，保留 2 位小數
     * 例如：512 → 512.00, 5120 → 5.12K, 5120000 → 5.12M
     */
    public static formatCompact(value: number, decimalPlaces: number = 2): string {
        const abs = Math.abs(value);
        const sign = value < 0 ? "-" : "";
        const units: [number, string][] = [
            [1e12, "T"],
            [1e9, "B"],
            [1e6, "M"],
            [1e3, "K"],
        ];
        for (const [threshold, suffix] of units) {
            if (abs >= threshold) {
                return sign + (abs / threshold).toFixed(decimalPlaces) + suffix;
            }
        }
        return sign + abs.toFixed(decimalPlaces);
    }

    public static getLength(data: any[] | object): number {
        if (Array.isArray(data)) {
            return data.length;
        }
        return Object.keys(data).length;
    }

    public static getWebURL() {
        return (typeof window !== "undefined" && window.location) ? window.location.href : "";
    }
    public static getURLParam(key: string) {
        if (typeof window === "undefined" || !window.location) return null;
        const urlParams = new URLSearchParams(window.location.search);
        return urlParams.get(key);
    }

    public static getDomainName() {
        return (typeof window !== "undefined" && window.location) ? window.location.origin : "";
    }

}
